import{_ as i,o as s,c as l,a5 as t}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"作品篇：把学会变成做出","description":"把输入、练习、反馈和交付组织成一条作品路径，让英语、AI 与职业学习留下可以展示、复测和复用的成果。","frontmatter":{"title":"作品篇：把学会变成做出","description":"把输入、练习、反馈和交付组织成一条作品路径，让英语、AI 与职业学习留下可以展示、复测和复用的成果。","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-3/4-artifacts-and-delivery.md","filePath":"threads/part-3/4-artifacts-and-delivery.md","lastUpdated":1788220800000}'),n={name:"threads/part-3/4-artifacts-and-delivery.md"};function e(r,a,h,o,p,d){return s(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="作品篇-把学会变成做出" tabindex="-1">作品篇：把学会变成做出 <a class="header-anchor" href="#作品篇-把学会变成做出" aria-label="Permalink to &quot;作品篇：把学会变成做出&quot;">​</a></h1><p>“我已经学会了”是一种很舒服的感觉，也是一种很容易被误判的感觉。只要继续阅读、收藏和听讲，我们几乎总能找到熟悉感；真正困难的是关掉材料之后，仍然能够做出一个别人看得见、用得上、可以提出意见的东西。</p><p>我在软件公司失败之后才真正理解这一点。我们曾经拥有很多功能、演示和会议，却没有足够可靠的用户价值、数据基础和交付证据。后来重新学习 AI 和技术时，我给自己加了一条门槛：<strong>每一轮学习都要留下一个可以被检查的作品。</strong></p><p>作品不一定是产品，也可以是一封邮件、一段录音、一份报告、一张流程图、一个小工具、一次演示或一篇有来源的文章。它的共同点是：它把脑中的理解放到了现实面前，允许别人使用、质疑和改进。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>区分“知道、能做、能交付”，不要让熟悉感冒充能力；</li><li>用最小作品暴露问题，而不是先准备一个宏大项目；</li><li>让作品拥有受众、场景、完成标准和版本记录；</li><li>用 AI 加快拆解、反馈和测试，但保留自己的第一版与关键判断；</li><li>通过发布、复测和复盘，让作品在时间里形成可信的能力证据。</li></ul><h2 id="_1-三种不同的-会" tabindex="-1">1. 三种不同的“会” <a class="header-anchor" href="#_1-三种不同的-会" aria-label="Permalink to &quot;1. 三种不同的“会”&quot;">​</a></h2><p>学习过程中至少有三种状态：</p><ol><li><strong>知道</strong>：能读懂定义，听过解释，看到答案时觉得熟悉；</li><li><strong>能做</strong>：在相似条件下独立完成一次任务；</li><li><strong>能交付</strong>：在真实限制下完成、说明、修订，并让别人能够使用或评价。</li></ol><p>从知道到能做，需要主动回忆和重复；从能做到能交付，需要受众、时间、质量标准和责任。很多课程只带你到第一层，真正的职业能力往往在第三层才开始接受现实检验。</p><p>每学一个主题，可以问自己：</p><blockquote><p>如果现在不能打开搜索和聊天记录，我能做出什么？谁会看到它？什么结果算完成？</p></blockquote><h2 id="_2-先选择作品的大小" tabindex="-1">2. 先选择作品的大小 <a class="header-anchor" href="#_2-先选择作品的大小" aria-label="Permalink to &quot;2. 先选择作品的大小&quot;">​</a></h2><p>作品不应一开始就大到让你只能继续准备。按可用时间选择尺寸：</p><table tabindex="0"><thead><tr><th>尺寸</th><th>时长</th><th>示例</th><th>主要验证</th></tr></thead><tbody><tr><td>微型作品</td><td>10–30 分钟</td><td>三句英文说明、一个测试、一个流程草图</td><td>我是否理解了最小概念？</td></tr><tr><td>小型作品</td><td>1–3 小时</td><td>一封工作邮件、一份短报告、一个可运行脚本</td><td>我能否独立完成并解释？</td></tr><tr><td>项目作品</td><td>1–2 周</td><td>一个工具原型、一场演示、一组内容专题</td><td>真实受众是否愿意使用或反馈？</td></tr><tr><td>组合作品</td><td>4–12 周</td><td>多来源报告、课程、产品试点、作品集</td><td>能否稳定交付并迁移到新场景？</td></tr></tbody></table><p>先做小作品不是降低标准，而是提前购买反馈。一个两小时内能被看见的问题，比两个月后才发现的方向错误更便宜。</p><h2 id="_3-一页作品简报" tabindex="-1">3. 一页作品简报 <a class="header-anchor" href="#_3-一页作品简报" aria-label="Permalink to &quot;3. 一页作品简报&quot;">​</a></h2><p>在动手之前写一页，不用把所有细节都想清楚：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 作品简报 — YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">作品名称：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">受众/使用者：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">要解决的一个问题：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">输入材料与来源：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我当前的基线：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">关键假设：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最小交付物：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">格式与限制：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">完成标准：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">不做什么：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">第一版截止时间：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">谁会提供反馈：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">需要保留的证据：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">失败时如何缩小、暂停或回滚：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次复查日期：</span></span></code></pre></div><p>“不做什么”与“完成标准”同样重要。它们帮助你抵抗功能膨胀，也让反馈能够落到具体问题上。</p><h2 id="_4-四次经过作品" tabindex="-1">4. 四次经过作品 <a class="header-anchor" href="#_4-四次经过作品" aria-label="Permalink to &quot;4. 四次经过作品&quot;">​</a></h2><h3 id="第一遍-独立版" tabindex="-1">第一遍：独立版 <a class="header-anchor" href="#第一遍-独立版" aria-label="Permalink to &quot;第一遍：独立版&quot;">​</a></h3><p>先在不看答案、不让 AI 代写的情况下完成。速度可以慢，结果可以粗糙，但必须留下原始版本。没有第一版，就没有能力增长的对照。</p><h3 id="第二遍-结构版" tabindex="-1">第二遍：结构版 <a class="header-anchor" href="#第二遍-结构版" aria-label="Permalink to &quot;第二遍：结构版&quot;">​</a></h3><p>检查受众是否知道下一步，信息是否按重要性排列，事实和推测是否分开，失败路径是否被说明。先修结构，再修句子和颜色。</p><h3 id="第三遍-反馈版" tabindex="-1">第三遍：反馈版 <a class="header-anchor" href="#第三遍-反馈版" aria-label="Permalink to &quot;第三遍：反馈版&quot;">​</a></h3><p>把作品交给一个真实的人、一个小范围用户，或让 AI 扮演明确的审阅角色。反馈要回答三个问题：哪里有用？哪里造成误解？哪一个改动最值得先做？</p><h3 id="第四遍-交付版" tabindex="-1">第四遍：交付版 <a class="header-anchor" href="#第四遍-交付版" aria-label="Permalink to &quot;第四遍：交付版&quot;">​</a></h3><p>根据反馈修订，写清版本、限制、来源和已知问题。让别人能够在没有你口头补充的情况下开始使用，哪怕只能完成一个很小的动作。</p><h2 id="_5-ai-在作品中的位置" tabindex="-1">5. AI 在作品中的位置 <a class="header-anchor" href="#_5-ai-在作品中的位置" aria-label="Permalink to &quot;5. AI 在作品中的位置&quot;">​</a></h2><p>AI 可以成为四种助手：</p><ul><li><strong>拆解者</strong>：把目标拆成最小步骤和验收条件；</li><li><strong>陪练者</strong>：生成平行任务，让你在不同场景中重复；</li><li><strong>审阅者</strong>：按照受众、事实、结构、质量和风险提出问题；</li><li><strong>测试者</strong>：制造边界输入、反例和可能失败的路径。</li></ul><p>但以下部分最好由你亲自完成：定义问题，选择受众，写下第一版，确认事实，决定删掉什么，以及为最终结果署名。</p><p>一个实用的协作顺序是：</p><ol><li>自己写简报和第一版；</li><li>让 AI 只指出最影响结果的三个问题；</li><li>自己修改并保存差异；</li><li>让 AI 生成一个平行场景或反例；</li><li>关闭 AI，独立完成一次复测；</li><li>把来源、反馈、成本和未决问题写回作品记录。</li></ol><p>如果 AI 直接交付了最终成品，你可能获得一个漂亮的文件，却失去最重要的训练过程。</p><h2 id="_6-作品的质量门" tabindex="-1">6. 作品的质量门 <a class="header-anchor" href="#_6-作品的质量门" aria-label="Permalink to &quot;6. 作品的质量门&quot;">​</a></h2><p>不同作品的标准不同，但至少检查五道门：</p><ul><li><strong>清楚</strong>：受众知道它解决什么问题，下一步做什么；</li><li><strong>准确</strong>：事实、引用、代码和数字可以回到来源或测试；</li><li><strong>可用</strong>：在真实限制下能够完成主要动作，而不是只能演示；</li><li><strong>可维护</strong>：别人知道版本、依赖、限制和出现问题时找谁；</li><li><strong>可负责</strong>：敏感数据、隐私、版权和错误后果已经被考虑。</li></ul><p>速度、字数和功能数量都只是代理指标。一个更小但可解释、可复查、可修订的作品，通常比一份无法交接的宏大成品更有长期价值。</p><h2 id="_7-发布不是表演-而是获取信息" tabindex="-1">7. 发布不是表演，而是获取信息 <a class="header-anchor" href="#_7-发布不是表演-而是获取信息" aria-label="Permalink to &quot;7. 发布不是表演，而是获取信息&quot;">​</a></h2><p>公开发布不等于把隐私交给所有人。可以按风险选择受众：</p><ul><li>私人记录：只为自己保留过程和错误；</li><li>小范围试用：交给三到五位相关的人，记录他们是否能完成任务；</li><li>公开版本：删除不必要的个人信息，标注来源、限制和版本；</li><li>正式交付：写清授权、责任、支持范围、成本和退出方式。</li></ul><p>发布前问自己：我是否获得了必要授权？是否把第三方信息脱敏？是否会把一个未经证实的个人故事包装成结果证明？诚实的限制不会降低作品价值，反而让反馈更可靠。</p><h2 id="_8-7-天作品启动" tabindex="-1">8. 7 天作品启动 <a class="header-anchor" href="#_8-7-天作品启动" aria-label="Permalink to &quot;8. 7 天作品启动&quot;">​</a></h2><ol><li><strong>第 1 天</strong>：从正在学习的主题里选一个真实问题；</li><li><strong>第 2 天</strong>：写作品简报和无 AI 基线；</li><li><strong>第 3 天</strong>：完成微型或小型作品的第一版；</li><li><strong>第 4 天</strong>：让 AI 或同伴指出三个最高价值问题；</li><li><strong>第 5 天</strong>：自己修订，补齐来源、限制和失败路径；</li><li><strong>第 6 天</strong>：交给一个真实受众试用或阅读；</li><li><strong>第 7 天</strong>：记录反馈、决定下一版范围，并保存全部证据。</li></ol><p>如果七天只能完成一页、一段录音或一个能运行的最小脚本，也已经完成了一次从学习到交付的闭环。</p><h2 id="_9-12-周作品阶梯" tabindex="-1">9. 12 周作品阶梯 <a class="header-anchor" href="#_9-12-周作品阶梯" aria-label="Permalink to &quot;9. 12 周作品阶梯&quot;">​</a></h2><ul><li><strong>第 1–2 周</strong>：完成 4 个微型作品，确认主题和场景；</li><li><strong>第 3–5 周</strong>：完成 2 个小型作品，开始收集真实反馈；</li><li><strong>第 6–8 周</strong>：把一个小型作品扩展成可试用原型，记录成本和失败；</li><li><strong>第 9–12 周</strong>：完成一次公开或正式交付，用盲评、用户反馈或平行任务复测。</li></ul><p>每一级都留下原始版、修订版和反馈。作品数量不是目的，能够解释自己如何从问题走到结果，才是能力开始稳定的信号。</p><h2 id="_10-作品的阶段性标准" tabindex="-1">10. 作品的阶段性标准 <a class="header-anchor" href="#_10-作品的阶段性标准" aria-label="Permalink to &quot;10. 作品的阶段性标准&quot;">​</a></h2><p>你不需要等作品完美才称它为作品。一个合格的阶段成果通常能做到：</p><ul><li>有明确的受众和使用场景；</li><li>有一个可观察的完成标准；</li><li>有独立完成的原始版本；</li><li>有来自他人、测试或来源的反馈；</li><li>有版本、限制和下一步；</li><li>能在不依赖聊天记录的情况下解释关键决定。</li></ul><p>当作品允许别人看见、使用和质疑时，学习才真正离开了脑海，进入了世界。</p><h2 id="交付之后再问一次" tabindex="-1">交付之后再问一次 <a class="header-anchor" href="#交付之后再问一次" aria-label="Permalink to &quot;交付之后再问一次&quot;">​</a></h2><p>交付证明的是某个条件下的即时表现，不等于能力已经保持或能够迁移。完成作品后，打开<a href="./5-evidence-and-transfer">证据篇：变化要如何被看见</a>，再安排一次撤掉提示的延迟复测，以及一次换主题、听众或约束的迁移任务。保留原始版、交付版和复测版，才能看见作品是如何离开一次演示、进入真实使用的。</p><h2 id="结语-让作品替你记住" tabindex="-1">结语：让作品替你记住 <a class="header-anchor" href="#结语-让作品替你记住" aria-label="Permalink to &quot;结语：让作品替你记住&quot;">​</a></h2><p>知识会忘，情绪会变，聊天记录也可能消失。作品是另一种记忆：它提醒你曾经面对过什么问题，做过怎样的选择，在哪里犯错，又怎样把错误改成下一步。</p><p>我不再把“完成作品”理解成向世界证明自己很厉害。它更像是给未来的自己留一盏灯：当你再次怀疑是否能够开始时，至少有一件真实的东西可以回答——你已经做过一次。</p>`,59)])])}const g=i(n,[["render",e]]);export{k as __pageData,g as default};
